<script setup lang="ts">
import { computed, ref, watch } from 'vue'
import SceneDimensionsFields from './SceneDimensionsFields.vue'
import type { Scene, SceneFolder } from '../tabletop/types'
const props = defineProps<{
  folders:SceneFolder[];
  saveFolder:(id:string|null,name:string)=>Promise<boolean>
  removeFolder:(id:string)=>Promise<boolean>
  moveFolder:(sceneId:string,folderId:string|null)=>Promise<boolean>
  scenes: Scene[]; activeId: string; master: boolean; busy: boolean; error: string
  remove: (id: string) => Promise<boolean>
  create: (settings: object) => Promise<string | undefined>
  save: (id: string, settings: object) => Promise<boolean>
  activate: (id: string) => Promise<boolean>
  upload: (id: string, image: File) => Promise<boolean>
}>()
const sceneWidth=ref(3200),sceneHeight=ref(2200),newWidth=ref(3200),newHeight=ref(2200),newCell=ref(64)
const folderDialog=ref(false),folderName=ref(''),folderEditing=ref<string|null>(null),collapsed=ref(new Set<string>())
const folderId=ref(''),newFolderId=ref('')
const groups=computed(()=>props.master?[{id:'',name:'Sem pasta',scenes:props.scenes.filter(scene=>!scene.folder_id)},...props.folders.map(folder=>({...folder,scenes:props.scenes.filter(scene=>scene.folder_id===folder.id)}))]:[{id:'',name:'',scenes:props.scenes}])
function toggleFolder(id:string){if(collapsed.value.has(id))collapsed.value.delete(id);else collapsed.value.add(id)}
function editFolder(folder?:SceneFolder){folderEditing.value=folder?.id??null;folderName.value=folder?.name??'';folderDialog.value=true}
async function saveFolder(){if(await props.saveFolder(folderEditing.value,folderName.value))folderDialog.value=false}
async function removeFolder(id:string){await props.removeFolder(id)}
async function moveFolder(scene:Scene,event:Event){const input=event.target as HTMLSelectElement;if(!await props.moveFolder(scene.id,input.value||null))input.value=scene.folder_id||''}
const createDialog=ref(false),editDialog=ref(false)
const selected = ref(props.activeId), newName = ref(''), name = ref(''), cellSize = ref(64), amount = ref(1.5), unit = ref('m'), gridType = ref<Scene['grid_type']>('square'), snap = ref(true)
const gridColor=ref('#a29aad'),gridOpacity=ref(16)
const dirty = ref(false), localError = ref(''), fileInput = ref<HTMLInputElement>()
const current = computed(() => props.scenes.find(scene => scene.id === selected.value))
const units = [{value:'mm',label:'Milímetros (mm)'},{value:'cm',label:'Centímetros (cm)'},{value:'m',label:'Metros (m)'},{value:'km',label:'Quilômetros (km)'},{value:'in',label:'Polegadas (in)'},{value:'ft',label:'Pés / feet (ft)'},{value:'yd',label:'Jardas (yd)'},{value:'mi',label:'Milhas (mi)'}]
function fill() { const scene = current.value; if (!scene) return; folderId.value=scene.folder_id||'';sceneWidth.value=scene.width;sceneHeight.value=scene.height;name.value=scene.name;cellSize.value=scene.cell_size;amount.value=scene.distance_per_cell;unit.value=scene.distance_unit;gridType.value=scene.grid_type;gridColor.value=scene.grid_color;gridOpacity.value=Math.round(scene.grid_opacity*100);snap.value=scene.snap;dirty.value=false }
function select(id: string) { if (props.busy) return; if (dirty.value && !confirm('Descartar as alterações não salvas deste cenário?')) return; selected.value=id;localError.value='';fill();editDialog.value=props.master }
watch(() => props.scenes, () => { if (!current.value) selected.value=props.activeId; if (!dirty.value) fill() }, {immediate:true})
async function create() { localError.value='';const id=await props.create({name:newName.value,width:newWidth.value,height:newHeight.value,cell_size:newCell.value,folder_id:newFolderId.value||null});if(id){newName.value='';selected.value=id;fill();createDialog.value=false;editDialog.value=true} }
async function save() { if(!current.value)return; const ok=await props.save(current.value.id,{name:name.value,folder_id:folderId.value||null,width:sceneWidth.value,height:sceneHeight.value,cell_size:Number(cellSize.value),distance_per_cell:Number(amount.value),distance_unit:unit.value,grid_type:gridType.value,grid_visible:gridType.value!=='none',grid_color:gridColor.value,grid_opacity:Number(gridOpacity.value)/100,snap:snap.value});if(ok){dirty.value=false;fill();editDialog.value=false} }
async function upload(event: Event) {
  localError.value=''
  const input=event.target as HTMLInputElement, file=input.files?.[0]
  if (!file || !current.value) return
  if(file.size>10*1024*1024){localError.value='A imagem deve ter no máximo 10 MB.';input.value='';return}
  if(!['image/png','image/jpeg','image/webp'].includes(file.type)){localError.value='Selecione uma imagem PNG, JPEG ou WebP.';input.value='';return}
  await props.upload(current.value.id,file);input.value=''
}
async function removeScene(id:string){if(confirm('Excluir este cenário e seus tokens/objetos?'))await props.remove(id)}
</script>
<template>
  <section class="panel-content scenes-menu"><div class="panel-heading"><h2>Cenários</h2><span>{{ scenes.length }} {{ master ? 'NA CAMPANHA' : 'EM EXIBIÇÃO' }}</span></div><p class="panel-help">{{ master ? 'Prepare seus cenários e escolha qual exibir ao grupo.' : 'O mestre escolhe o cenário compartilhado com o grupo.' }}</p>
    <button v-if="master" class="primary full" :disabled="busy" @click="newName = ''; newWidth=3200;newHeight=2200;newCell=64;newFolderId=''; createDialog = true">+ Novo cenário</button>
    <button v-if="master" class="table-button new-folder" :disabled="busy" @click="editFolder()">+ Nova pasta</button>
    <section v-for="group in groups" :key="group.id" class="scene-folder" :aria-label="master ? `Pasta ${group.name}` : 'Cenário em exibição'">
      <div v-if="master" class="folder-heading"><button class="folder-toggle" :aria-expanded="!collapsed.has(group.id)" @click="toggleFolder(group.id)"><span aria-hidden="true">{{ collapsed.has(group.id) ? '▸' : '▾' }} ▰</span> {{ group.name }} <small>{{ group.scenes.length }}</small></button><template v-if="group.id"><button :aria-label="`Renomear pasta ${group.name}`" :disabled="busy" @click="editFolder(group)">✎</button><button :aria-label="`Excluir pasta ${group.name}`" title="Excluir pasta e manter cenários em Sem pasta" :disabled="busy" @click="removeFolder(group.id)">×</button></template></div>
    <ul v-show="!collapsed.has(group.id)" class="scenes-list"><li v-for="scene in group.scenes" :key="scene.id" class="scene-card"><button :class="{ chosen: activeId === scene.id }" :disabled="busy || !master" @click="select(scene.id)"><img v-if="scene.background_url" :src="scene.background_url" alt="" loading="lazy"><span v-else class="scene-thumb">▦</span><span><strong>{{ scene.name }}</strong><small>{{ scene.distance_per_cell }} {{ scene.distance_unit }} por quadrado</small></span><b v-if="activeId === scene.id">ATIVO</b></button><div v-if="master" class="scene-card-actions"><button :aria-label="`Editar ${scene.name}`" :disabled="busy" @click="select(scene.id)">Editar</button><button v-if="scene.id !== activeId" :disabled="busy" @click="activate(scene.id)">Exibir na mesa</button><button :aria-label="`Excluir ${scene.name}`" :disabled="busy || scenes.length <= 1" :title="scenes.length <= 1 ? 'A mesa deve ter pelo menos um cenário' : 'Excluir cenário'" @click="removeScene(scene.id)">Excluir</button></div><label v-if="master" class="move-scene-folder"><span class="sr-only">Pasta de {{ scene.name }}</span><select :value="scene.folder_id || ''" :disabled="busy" :aria-label="`Mover ${scene.name} para pasta`" @change="moveFolder(scene,$event)"><option value="">Sem pasta</option><option v-for="folder in folders" :key="folder.id" :value="folder.id">{{ folder.name }}</option></select></label></li></ul>
      <p v-if="master && !collapsed.has(group.id) && !group.scenes.length" class="empty-folder">Nenhum cenário nesta pasta.</p>
    </section>
    <q-dialog v-model="folderDialog" :persistent="busy"><q-card class="modal scene-modal"><q-card-section><h2>{{ folderEditing ? 'Renomear pasta' : 'Nova pasta' }}</h2><form @submit.prevent="saveFolder"><label>Nome da pasta<input v-model="folderName" required maxlength="100" autofocus :disabled="busy"></label><p v-if="error" role="alert" class="scene-upload-error">{{ error }}</p><div class="modal-actions"><button type="button" class="text-button" :disabled="busy" @click="folderDialog=false">Cancelar</button><button class="primary" :disabled="busy">{{ folderEditing ? 'Salvar pasta' : 'Criar pasta' }}</button></div></form></q-card-section></q-card></q-dialog>
    <q-dialog v-model="createDialog" :persistent="busy"><q-card class="modal scene-modal"><q-card-section><span class="eyebrow">UMA NOVA PAISAGEM</span><h2>Novo cenário</h2><form @submit.prevent="create"><label>Nome do novo cenário<input v-model="newName" required maxlength="100" autofocus placeholder="Ex.: Floresta dos ecos" :disabled="busy"></label><label for="new-scene-folder">Pasta do novo cenário</label><select id="new-scene-folder" v-model="newFolderId" :disabled="busy"><option value="">Sem pasta</option><option v-for="folder in folders" :key="folder.id" :value="folder.id">{{ folder.name }}</option></select><SceneDimensionsFields :width="newWidth" :height="newHeight" :cell="newCell" :disabled="busy" @change="newWidth=$event.width;newHeight=$event.height;newCell=$event.cell" /><p v-if="error" role="alert" class="scene-upload-error">{{ error }}</p><div class="modal-actions"><button type="button" class="text-button" :disabled="busy" @click="createDialog = false">Cancelar</button><button class="primary" :disabled="busy">Criar cenário</button></div></form></q-card-section></q-card></q-dialog>
    <q-dialog v-model="editDialog" :persistent="busy"><q-card v-if="current" class="modal scene-modal"><q-card-section><span class="eyebrow">CONFIGURAÇÃO DO CENÁRIO</span><h2>Editar cenário</h2><form @submit.prevent="save" @input="dirty = true" @change="dirty = true"><label>Nome do cenário<input v-model="name" required maxlength="100" :disabled="busy"></label><label for="edit-scene-folder">Pasta do cenário</label><select id="edit-scene-folder" v-model="folderId" :disabled="busy"><option value="">Sem pasta</option><option v-for="folder in folders" :key="folder.id" :value="folder.id">{{ folder.name }}</option></select><SceneDimensionsFields :width="sceneWidth" :height="sceneHeight" :cell="cellSize" :disabled="busy" @change="sceneWidth=$event.width;sceneHeight=$event.height;cellSize=$event.cell;dirty=true" /><label>Distância por quadrado<input v-model="amount" type="number" min="0.000001" max="1000000000" step="any" required :disabled="busy"></label><label for="scene-distance-unit">Unidade de distância</label><select id="scene-distance-unit" v-model="unit" :disabled="busy"><option v-for="item in units" :key="item.value" :value="item.value">{{ item.label }}</option></select><label for="scene-grid-type">Tipo de grid</label><select id="scene-grid-type" v-model="gridType" :disabled="busy"><option value="square">Quadrado</option><option value="hex">Hexagonal</option><option value="none">Nenhum</option></select><p v-if="gridType === 'none'" class="panel-help">Sem grid: cor e opacidade ficam bloqueadas. Seus valores serão preservados.</p><fieldset class="grid-appearance" :disabled="busy || gridType === 'none'"><legend>Aparência das linhas do grid</legend><div class="grid-color-fields"><label>Cor das linhas do grid<input v-model="gridColor" type="color"></label><label>Código da cor do grid<input v-model="gridColor" type="text" pattern="#[0-9a-fA-F]{6}" maxlength="7" required spellcheck="false" placeholder="#a29aad"></label></div><label for="grid-opacity-number">Opacidade das linhas do grid (%)</label><div class="grid-opacity-controls"><input id="grid-opacity-number" v-model.number="gridOpacity" type="number" min="0" max="100" step="1" required aria-describedby="grid-opacity-help"><input v-model.number="gridOpacity" type="range" min="0" max="100" step="1" aria-label="Ajustar opacidade do grid" aria-describedby="grid-opacity-help"></div><p id="grid-opacity-help" class="panel-help">Digite uma porcentagem ou arraste a barra. 0% deixa as linhas transparentes; 100% deixa as linhas opacas.</p></fieldset><label class="table-checkbox"><input v-model="snap" type="checkbox" :disabled="busy || gridType === 'none'"> Encaixar tokens no grid</label><p v-if="error" role="alert" class="scene-upload-error">{{ error }}</p><div class="modal-actions"><button type="button" class="text-button" :disabled="busy" @click="editDialog = false; dirty = false">Fechar</button><button class="primary" :disabled="busy || !dirty">Salvar cenário</button></div></form>
      <div class="scene-background"><h3>Imagem principal de fundo</h3><img v-if="current.background_url" :src="current.background_url" :alt="`Fundo de ${current.name}`" class="scene-preview"><label>Selecionar imagem<input ref="fileInput" type="file" accept="image/png,image/jpeg,image/webp" :disabled="busy" @change="upload"></label><p class="panel-help">Até 10 MB. Para mover ou redimensionar, selecione a camada Fundo e dê dois cliques na imagem.</p><p v-if="localError" role="alert" class="scene-upload-error">{{ localError }}</p></div>
    </q-card-section></q-card></q-dialog>
  </section>
</template>
<style scoped>.new-folder{width:100%;margin-top:10px}.scene-folder{margin-top:18px}.folder-heading{display:flex;align-items:center;gap:6px;border-bottom:1px solid #493254;padding-bottom:6px}.folder-heading button{background:none;color:#cdb6df;border:0;padding:7px;cursor:pointer}.folder-heading .folder-toggle{display:flex;align-items:center;gap:7px;flex:1;min-width:0;text-align:left;overflow-wrap:anywhere}.folder-toggle small{margin-left:auto;color:#a18aad}.empty-folder{font-size:11px;color:#a18aad;padding:12px}.move-scene-folder{margin:-8px 0 18px}.move-scene-folder select{width:100%;background:#17111e;color:#cdb6df;border:1px solid #493254;border-radius:6px;padding:7px;font-size:11px}.scene-folder .scenes-list{margin-top:10px}.grid-appearance:disabled{opacity:.5}.grid-appearance:disabled input{cursor:not-allowed}.grid-appearance{border:1px solid #59436a;border-radius:8px;margin:20px 0;padding:0 14px 14px;min-width:0}.grid-appearance legend{font-size:12px;color:#cbb6dd;padding:0 6px}.grid-color-fields{display:grid;grid-template-columns:1fr 2fr;gap:14px}.grid-color-fields input[type=color]{height:44px;padding:4px;cursor:pointer}.grid-opacity-controls{display:flex;align-items:center;gap:16px}.grid-opacity-controls input[type=number]{width:90px;flex-shrink:0}.grid-opacity-controls input[type=range]{flex:1;min-width:0;padding:0;accent-color:#b48ce9;cursor:pointer}.grid-appearance .panel-help{margin:12px 0 0}.scenes-list{list-style:none;margin:0;padding:0}.scenes-list li{margin-bottom:8px}.scenes-list button{width:100%;display:flex;gap:10px;align-items:center;text-align:left;border:1px solid #493254;background:#251b30;color:#d6c1e6;border-radius:8px;padding:10px}.scenes-list button.chosen{border-color:#b98de2;background:#3b2849}.scenes-list img,.scene-thumb{width:45px;height:38px;border-radius:4px;object-fit:cover;flex-shrink:0;background:#4b3659;display:grid;place-items:center}.scene-thumb{font-size:23px;color:#b49ac6}.scenes-list strong{display:block;font-size:11px;overflow-wrap:anywhere;font-weight:500}.scenes-list small{display:block;font-size:9px;color:#ae92c2;margin-top:5px}.scenes-list b{margin-left:auto;font-size:7px;letter-spacing:1px;color:#bfdaa5}.create-scene,.scene-editor{border-top:1px solid #483153;margin-top:24px;padding-top:20px}.scene-editor h3{font-size:13px;line-height:1.6;font-weight:500;margin-bottom:12px}.scene-background{margin-top:25px;padding-top:20px;border-top:1px solid #483153}.scene-preview{max-width:100%;max-height:160px;object-fit:contain;border-radius:7px;background:#130f19}.scene-upload-error{color:#ffc0d0;font-size:11px}.scene-background input[type=file]{font-size:10px;max-width:100%}.scenes-list{margin-top:22px}.scene-card-actions{display:flex;gap:6px;margin:6px 0 18px}.scene-card-actions button{font-size:10px;padding:7px;justify-content:center}.scene-modal select{width:100%;padding:12px;background:#17111e;color:#e3d5ed;border:1px solid #5d426c;border-radius:7px}.scene-modal label{color:#cbb6dd}.scene-modal .scene-upload-error{color:#ffc0d0}.scene-modal{max-height:88vh;overflow:auto}</style>
